insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('moong-dal-chilla-paneer', 'Moong dal chilla with paneer filling', 'Two crisp lentil pancakes stuffed with spiced paneer. A filling breakfast with over 20 g of protein and no protein powder.', 1, 10, 15, 403, 24.5, 40.5, 16.2, '[{"item":"60 g yellow moong dal, soaked 3 to 4 hours","grams":60},{"item":"50 g paneer, crumbled","grams":50},{"item":"1 small onion, finely chopped","grams":30},{"item":"½ tomato, finely chopped","grams":30},{"item":"1 tsp oil","grams":5},{"item":"Green chilli, ginger, coriander, salt, ¼ tsp turmeric","grams":null}]'::jsonb, '["Drain the soaked dal and blend with the chilli, ginger, salt and a few tablespoons of water into a smooth, pourable batter.","Mix the paneer with half the onion, the tomato and coriander for the filling.","Heat a non-stick tawa, brush with a few drops of oil and spread half the batter thin. Sprinkle the remaining onion on top.","Cook on medium heat until the edges lift, flip, and cook 1 minute more.","Spread half the filling on one side, fold, and repeat for the second chilla."]'::jsonb, array['breakfast','high_protein_veg','fat_loss']::text[], array['vegetarian','gluten_free']::text[], 'Soak the dal the night before so breakfast takes 15 minutes. Batter keeps 2 days in the fridge.', 0)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('besan-chilla-spinach', 'Besan and spinach chilla with curd dip', 'A 15-minute savoury pancake made from chickpea flour and spinach, served with a thick hung-curd dip.', 1, 5, 10, 328, 22.6, 36.1, 10.4, '[{"item":"50 g besan (about 5 tbsp)","grams":50},{"item":"A handful of spinach, chopped","grams":40},{"item":"2 tbsp chopped onion","grams":20},{"item":"1 tsp oil","grams":5},{"item":"100 g hung curd, for the dip","grams":100},{"item":"Ajwain, chilli, salt, mint for the dip","grams":null}]'::jsonb, '["Whisk the besan with salt, ajwain and about 80 ml water into a lump-free batter. Stir in the spinach and onion.","Heat a tawa, add a few drops of oil and spread the batter into one large or two small chillas.","Cook 2 to 3 minutes per side until golden spots appear.","Mix the hung curd with chopped mint, salt and a pinch of roasted jeera for the dip."]'::jsonb, array['breakfast','high_protein_veg','fat_loss','office']::text[], array['vegetarian','gluten_free']::text[], 'Pack the chilla in a foil roll with the dip in a small box for an office breakfast.', 1)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('overnight-oats-whey-chia', 'Overnight oats with whey and chia', 'Mix it in two minutes at night, eat it cold the next morning. About 37 g of protein for a commute breakfast.', 1, 5, 0, 499, 37, 61.2, 12.8, '[{"item":"50 g rolled oats","grams":50},{"item":"150 ml toned milk","grams":150},{"item":"1 scoop (30 g) whey protein","grams":30},{"item":"2 tsp chia seeds","grams":10},{"item":"½ banana, sliced","grams":60}]'::jsonb, '["In a jar, whisk the whey into the milk first so it does not clump.","Stir in the oats and chia seeds. Close the jar and refrigerate overnight.","In the morning, top with banana. Loosen with a splash of milk if it is too thick."]'::jsonb, array['breakfast','office','pre_workout','muscle_gain']::text[], array['vegetarian']::text[], 'No whey? Use 150 g hung curd instead of the whey and half the milk.', 2)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('soya-chunk-pulao', 'Soya chunk pulao with raita', 'A one-pot lunch where soya chunks do the heavy lifting on protein. Packs well for the office.', 1, 15, 20, 528, 31.2, 75.4, 11.1, '[{"item":"40 g soya chunks (dry weight)","grams":40},{"item":"60 g rice, rinsed and soaked 15 minutes","grams":60},{"item":"¼ cup green peas","grams":40},{"item":"1 small onion, sliced","grams":40},{"item":"1½ tsp oil or ghee","grams":7},{"item":"100 g curd, for raita","grams":100},{"item":"Bay leaf, jeera, ginger-garlic paste, garam masala, salt","grams":null}]'::jsonb, '["Soak the soya chunks in hot salted water for 10 minutes, then squeeze out all the water.","Heat the oil in a pressure cooker, add jeera and bay leaf, then the onion. Cook until golden.","Add ginger-garlic paste, the soya chunks, peas and garam masala. Stir for 2 minutes.","Add the drained rice and 1¼ cups water with salt. Pressure cook for 2 whistles and rest 10 minutes.","Whisk the curd with salt and roasted jeera and serve on the side."]'::jsonb, array['lunch','high_protein_veg','muscle_gain','office']::text[], array['vegetarian']::text[], 'Squeezing the soaked chunks well is what makes them soak up the masala instead of tasting rubbery.', 3)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('paneer-bhurji', 'Paneer bhurji', 'Scrambled paneer with onion, tomato and capsicum. Ten minutes, one pan, about 20 g of protein.', 1, 5, 10, 342, 19.6, 8.6, 26, '[{"item":"100 g paneer, crumbled","grams":100},{"item":"1 small onion, chopped","grams":40},{"item":"1 tomato, chopped","grams":60},{"item":"¼ capsicum, chopped","grams":30},{"item":"1 tsp oil","grams":5},{"item":"Jeera, green chilli, turmeric, chilli powder, salt, coriander","grams":null}]'::jsonb, '["Heat the oil, add jeera and chilli, then the onion. Cook until soft.","Add the capsicum and tomato with turmeric, chilli powder and salt. Cook until the tomato breaks down.","Add the paneer, mix gently and cook 2 minutes. Finish with coriander."]'::jsonb, array['dinner','breakfast','high_protein_veg','muscle_gain']::text[], array['vegetarian','gluten_free']::text[], 'For fat loss, swap half the paneer for 50 g crumbled firm tofu. The texture is almost identical.', 4)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('rajma-brown-rice-bowl', 'Rajma brown rice bowl', 'Classic rajma with brown rice and a crunchy cucumber salad. Plenty of fibre to keep you full through the afternoon.', 1, 10, 40, 439, 16.7, 78.5, 7.4, '[{"item":"50 g rajma, soaked overnight","grams":50},{"item":"50 g brown rice","grams":50},{"item":"1 small onion, chopped","grams":40},{"item":"1 large tomato, pureed","grams":80},{"item":"1 tsp oil","grams":5},{"item":"½ cucumber, diced, for salad","grams":80},{"item":"Ginger-garlic paste, rajma masala or garam masala, salt","grams":null}]'::jsonb, '["Pressure cook the soaked rajma with salt for 5 to 6 whistles until fully soft.","Cook the brown rice with twice its volume of water for about 25 minutes, or 3 whistles in a cooker.","Heat the oil, cook the onion until brown, add ginger-garlic paste, then the tomato and masala. Cook until oil separates.","Add the rajma with its water and simmer 10 minutes, mashing a few beans to thicken.","Serve over the rice with the cucumber salad on the side."]'::jsonb, array['lunch','high_protein_veg','office']::text[], array['vegetarian','vegan','gluten_free']::text[], 'Cook rajma in bulk on Sunday. It keeps 4 days in the fridge and freezes well.', 5)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('chana-chaat', 'Chana chaat', 'Tangy chickpea salad you can assemble at your desk. No cooking if you keep boiled chana in the fridge.', 1, 10, 0, 275, 14.4, 47.9, 4.1, '[{"item":"1 cup boiled kabuli chana (150 g)","grams":150},{"item":"¼ onion, chopped","grams":30},{"item":"½ tomato, chopped","grams":40},{"item":"¼ cucumber, chopped","grams":50},{"item":"Juice of ½ lemon","grams":10},{"item":"Chaat masala, roasted jeera, green chilli, coriander, salt","grams":null}]'::jsonb, '["Combine the chana, onion, tomato and cucumber in a bowl.","Add lemon juice, chaat masala, roasted jeera, chilli and salt. Toss.","Top with coriander and eat within a few hours so the vegetables stay crisp."]'::jsonb, array['snacks','office','fat_loss','lunch']::text[], array['vegetarian','vegan','gluten_free']::text[], 'Add 50 g crumbled paneer for about 9 g more protein.', 6)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('moong-sprouts-salad', 'Moong sprouts salad with peanuts', 'Home-sprouted moong with pomegranate, cucumber and a few peanuts for crunch. A light snack that travels well.', 1, 10, 3, 245, 13.6, 38.2, 5.9, '[{"item":"40 g whole moong (dry weight), sprouted","grams":40},{"item":"2 tbsp chopped onion","grams":20},{"item":"½ tomato, chopped","grams":40},{"item":"¼ cucumber, chopped","grams":50},{"item":"2 tbsp pomegranate seeds","grams":30},{"item":"1 tbsp roasted peanuts","grams":10},{"item":"Juice of ½ lemon","grams":10},{"item":"Chaat masala, salt, coriander","grams":null}]'::jsonb, '["Soak the moong for 8 hours, drain, and leave covered for 12 to 24 hours until short sprouts appear.","Steam or boil the sprouts for 2 to 3 minutes. This makes them easier to digest. Cool.","Toss with the vegetables, pomegranate, lemon juice, chaat masala and salt. Top with peanuts."]'::jsonb, array['snacks','office','fat_loss']::text[], array['vegetarian','vegan','gluten_free']::text[], 'Macros are based on the dry weight of moong before sprouting, which is the easiest way to measure.', 7)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('tofu-tikka', 'Tofu tikka', 'Firm tofu marinated in hung curd and spices, cooked in a pan or air fryer with capsicum and onion.', 1, 20, 12, 323, 31.8, 12.2, 19.1, '[{"item":"150 g firm tofu, pressed and cubed","grams":150},{"item":"50 g hung curd","grams":50},{"item":"½ capsicum, in squares","grams":50},{"item":"1 small onion, in petals","grams":40},{"item":"1 tsp oil","grams":5},{"item":"Ginger-garlic paste, kashmiri chilli, tandoori masala, kasuri methi, lemon, salt","grams":null}]'::jsonb, '["Press the tofu between kitchen towels under a heavy pan for 10 minutes, then cube.","Mix the hung curd with ginger-garlic paste, spices, kasuri methi, lemon and salt. Coat the tofu and vegetables. Rest 15 minutes.","Cook in a hot pan with the oil for 8 to 10 minutes, turning to char each side. Or air fry at 200°C for 12 minutes."]'::jsonb, array['dinner','high_protein_veg','fat_loss']::text[], array['vegetarian','gluten_free']::text[], 'Use paneer instead of tofu for a richer version; the calories go up by about 180.', 8)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('hung-curd-parfait', 'Hung curd parfait', 'Layers of thick curd, apple, oats and almonds. A sweet-tooth snack with 20+ g of protein.', 1, 5, 0, 343, 25, 40.3, 10.3, '[{"item":"200 g hung curd or plain Greek yogurt","grams":200},{"item":"½ apple, diced","grams":80},{"item":"2 tbsp oats, dry-roasted","grams":20},{"item":"7 to 8 almonds, chopped","grams":10},{"item":"1 tsp honey","grams":7},{"item":"Cinnamon","grams":null}]'::jsonb, '["Dry-roast the oats in a pan for 2 minutes until fragrant.","In a glass or box, layer half the curd, half the apple and oats, then repeat.","Top with almonds, cinnamon and honey."]'::jsonb, array['snacks','post_workout','breakfast','office']::text[], array['vegetarian']::text[], 'To make hung curd, tie regular curd in a muslin cloth and hang it in the fridge for 4 to 6 hours.', 9)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('sattu-drink', 'Namkeen sattu drink', 'The Bihari classic: roasted chana flour whisked with water, lemon and jeera. Ready in 2 minutes before a workout.', 1, 2, 0, 158, 9, 25.6, 2.2, '[{"item":"40 g sattu (4 tbsp)","grams":40},{"item":"Juice of ½ lemon","grams":10},{"item":"1 tbsp finely chopped onion (optional)","grams":10},{"item":"Roasted jeera powder, black salt, mint, 300 ml cold water","grams":null}]'::jsonb, '["Whisk the sattu into the water until smooth.","Add lemon, roasted jeera, black salt, mint and onion. Stir and drink."]'::jsonb, array['pre_workout','office','snacks']::text[], array['vegetarian','vegan','gluten_free']::text[], 'Sattu values vary by brand; check the pack for protein per 100 g.', 10)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('masoor-dal-palak-roti', 'Masoor dal palak with two rotis', 'Everyday dal made heartier with spinach, served with two rotis and a spoon of ghee. A complete plate.', 1, 10, 20, 458, 22, 80.9, 7.9, '[{"item":"50 g masoor dal","grams":50},{"item":"A large handful of spinach","grams":50},{"item":"½ tomato","grams":40},{"item":"¼ onion","grams":30},{"item":"60 g atta, for 2 rotis","grams":60},{"item":"1 tsp ghee, for tadka","grams":5},{"item":"Jeera, garlic, red chilli, turmeric, salt","grams":null}]'::jsonb, '["Pressure cook the dal with turmeric, salt and 1½ cups water for 2 whistles.","Add chopped spinach and tomato and simmer 5 minutes.","For the tadka, heat ghee, add jeera, garlic, onion and red chilli, and pour over the dal.","Make two thin rotis from the atta and serve."]'::jsonb, array['lunch','dinner','high_protein_veg']::text[], array['vegetarian']::text[], 'A katori of curd (150 g) on the side adds about 5 g of protein.', 11)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('egg-bhurji-toast', 'Egg bhurji on whole wheat toast', 'Two whole eggs plus two whites, scrambled desi-style and served on toast. For eggetarians who want close to 28 g of protein, fast.', 1, 5, 8, 382, 27.5, 29.4, 16.7, '[{"item":"2 whole eggs","grams":100},{"item":"2 egg whites","grams":66},{"item":"¼ onion, chopped","grams":30},{"item":"½ tomato, chopped","grams":40},{"item":"1 tsp oil","grams":5},{"item":"2 slices whole wheat bread","grams":56},{"item":"Green chilli, turmeric, pepper, salt, coriander","grams":null}]'::jsonb, '["Whisk the eggs and whites with salt and turmeric.","Cook the onion, chilli and tomato in the oil for 3 minutes.","Pour in the eggs and stir on low heat until just set.","Serve on toasted bread with coriander and pepper."]'::jsonb, array['breakfast','muscle_gain','post_workout']::text[], array['eggetarian']::text[], 'Cooking on low heat keeps the eggs soft; high heat makes them dry and rubbery.', 12)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('banana-peanut-whey-shake', 'Banana peanut butter whey shake', 'A post-workout shake with protein, carbs to refuel and a little peanut butter for taste.', 1, 3, 0, 413, 34.8, 38.9, 14.6, '[{"item":"250 ml toned milk","grams":250},{"item":"1 scoop (30 g) whey protein","grams":30},{"item":"1 medium banana","grams":100},{"item":"2 tsp peanut butter","grams":10},{"item":"Ice, cinnamon","grams":null}]'::jsonb, '["Blend everything for 30 seconds and drink."]'::jsonb, array['post_workout','muscle_gain','snacks']::text[], array['vegetarian','gluten_free']::text[], 'For fat loss, use water instead of half the milk and skip the peanut butter: about 130 kcal less.', 13)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('roasted-makhana-peanuts', 'Roasted makhana and peanuts', 'A crunchy desk-drawer snack that beats namkeen. Make a week''s worth in 10 minutes.', 1, 2, 8, 220, 8.5, 21.8, 12, '[{"item":"30 g makhana (about 1½ cups)","grams":30},{"item":"1 tbsp peanuts","grams":15},{"item":"¾ tsp ghee","grams":4},{"item":"Black pepper, chaat masala or peri-peri, salt","grams":null}]'::jsonb, '["Dry-roast the peanuts in a pan for 3 minutes and set aside.","Warm the ghee, add makhana and roast on low heat for 5 to 6 minutes, stirring, until they crunch when pressed.","Toss with peanuts and seasoning. Cool fully before storing in an airtight jar."]'::jsonb, array['snacks','office']::text[], array['vegetarian','gluten_free','jain']::text[], 'This is a lighter, lower-protein snack. Pair it with a glass of milk or a protein shake if you need more.', 14)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('paneer-veg-wrap', 'Paneer and veg wrap', 'A whole wheat roti rolled around spiced paneer, crunchy vegetables and a mint-curd sauce. Easy to eat at your desk.', 1, 10, 10, 443, 24.3, 44, 20.5, '[{"item":"50 g atta, for one large roti","grams":50},{"item":"75 g paneer, in strips","grams":75},{"item":"¼ onion, sliced","grams":30},{"item":"¼ capsicum, sliced","grams":30},{"item":"A handful of shredded cabbage","grams":30},{"item":"2 tbsp hung curd with mint","grams":30},{"item":"½ tsp oil","grams":3},{"item":"Tikka masala, chaat masala, salt","grams":null}]'::jsonb, '["Make one large, thin roti.","Toss the paneer, onion and capsicum with masala and cook in the oil for 4 minutes.","Spread the mint-curd on the roti, add cabbage and the paneer mix, and roll tightly.","Wrap in butter paper or foil to carry."]'::jsonb, array['lunch','office','high_protein_veg']::text[], array['vegetarian']::text[], 'Use a ready whole wheat wrap if you are short on time; check the label for calories.', 15)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('palak-tofu', 'Palak tofu', 'Palak paneer''s lighter cousin: tofu in a smooth spinach gravy. Fewer calories, similar protein.', 1, 10, 20, 336, 31.1, 14.9, 20.8, '[{"item":"150 g firm tofu, cubed","grams":150},{"item":"1 large bunch spinach (150 g)","grams":150},{"item":"1 small onion","grams":40},{"item":"½ tomato","grams":40},{"item":"1½ tsp oil","grams":7},{"item":"Garlic, ginger, green chilli, jeera, garam masala, salt","grams":null}]'::jsonb, '["Blanch the spinach in boiling water for 2 minutes, then plunge into cold water and blend smooth with chilli.","Heat the oil, add jeera, garlic, ginger and onion; cook until soft. Add tomato and cook down.","Add the spinach puree, salt and garam masala, and simmer 5 minutes.","Add the tofu and simmer 3 more minutes."]'::jsonb, array['dinner','high_protein_veg','fat_loss']::text[], array['vegetarian','vegan','gluten_free']::text[], 'Serve with one roti or a small bowl of rice depending on your carb target.', 16)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('moong-dal-veg-khichdi', 'Moong dal vegetable khichdi', 'Comfort food that still fits a plan. Moong dal, rice and vegetables cooked together, with curd on the side.', 1, 10, 20, 436, 18.6, 70, 9.3, '[{"item":"40 g yellow moong dal","grams":40},{"item":"40 g rice","grams":40},{"item":"¼ carrot, diced","grams":30},{"item":"2 tbsp peas","grams":30},{"item":"4 to 5 french beans, chopped","grams":30},{"item":"1 tsp ghee","grams":5},{"item":"100 g curd, on the side","grams":100},{"item":"Jeera, hing, turmeric, ginger, salt","grams":null}]'::jsonb, '["Rinse the dal and rice together.","Heat ghee in a cooker, add jeera, hing and ginger, then the vegetables. Stir 2 minutes.","Add dal, rice, turmeric, salt and 3 cups water. Pressure cook for 3 whistles.","Rest, stir well, and serve with curd."]'::jsonb, array['dinner','lunch']::text[], array['vegetarian','gluten_free']::text[], 'Use more dal than rice (for example 50 g dal and 30 g rice) to push protein higher.', 17)
on conflict (slug) do nothing;
insert into public.recipes (slug, title, summary, servings, prep_minutes, cook_minutes, calories, protein_g, carbs_g, fat_g, ingredients, steps, categories, diet_tags, tips, sort_order)
values ('poha-peanuts-peas', 'Poha with peanuts and peas, curd on the side', 'A lighter Maharashtrian-style poha. Poha alone is low in protein, so this one comes with a bowl of curd.', 1, 5, 10, 431, 14.4, 55.6, 18.1, '[{"item":"50 g thick poha","grams":50},{"item":"1 tbsp peanuts","grams":15},{"item":"2 tbsp peas","grams":30},{"item":"¼ onion, chopped","grams":30},{"item":"1 tsp oil","grams":5},{"item":"A squeeze of lemon","grams":5},{"item":"150 g curd, on the side","grams":150},{"item":"Mustard seeds, curry leaves, turmeric, green chilli, salt, coriander","grams":null}]'::jsonb, '["Rinse the poha in a strainer, drain and leave for 5 minutes to soften.","Heat oil, roast the peanuts, then add mustard seeds, curry leaves and chilli.","Add the onion and peas and cook 3 minutes. Add turmeric, salt and the poha. Mix gently on low heat for 2 minutes.","Finish with lemon and coriander and serve with curd."]'::jsonb, array['breakfast']::text[], array['vegetarian','gluten_free']::text[], 'Swap the curd for 150 g hung curd to add about 10 g more protein.', 18)
on conflict (slug) do nothing;

insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('goblet-squat', 'Goblet squat', 'legs', 'dumbbell', 'beginner', 'The easiest way to learn a good squat. Holding the weight in front keeps your chest up.', '["Hold one dumbbell vertically at your chest, elbows pointing down.","Stand with feet a little wider than hips, toes turned slightly out.","Sit down between your heels, keeping the weight close to your chest.","Go as low as you can with a neutral back, then drive up through the whole foot."]'::jsonb, '["Knees track over your toes","Chest stays tall","Whole foot on the floor"]'::jsonb, '["Heels lifting off the floor","Knees caving inward on the way up"]'::jsonb, array['Bodyweight squat','Box squat','Leg press']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('bodyweight-squat', 'Bodyweight squat', 'legs', 'bodyweight', 'beginner', 'A no-equipment squat for home, hotel rooms and warm-ups.', '["Stand with feet shoulder-width apart, arms out in front for balance.","Push your hips back and bend your knees to sit down.","Stop when your thighs are near parallel or your back starts to round.","Stand up by pushing the floor away."]'::jsonb, '["Brace your stomach lightly","Control the way down"]'::jsonb, '["Rounding the lower back at the bottom","Rising onto the toes"]'::jsonb, array['Box squat','Split squat']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('barbell-back-squat', 'Barbell back squat', 'legs', 'barbell', 'intermediate', 'The main lower-body strength lift. Learn the goblet squat first.', '["Set the bar on your upper back, below the bony part of your neck, and grip it firmly.","Unrack, take two steps back and set your feet.","Take a big breath into your belly and brace.","Squat to the depth you can control, then drive up while keeping the bar over mid-foot."]'::jsonb, '["Breathe and brace before every rep","Bar path stays over mid-foot","Spread the floor with your feet"]'::jsonb, '["Chest dropping so the squat turns into a good-morning","Losing brace at the bottom"]'::jsonb, array['Goblet squat','Leg press','Bulgarian split squat']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('romanian-deadlift', 'Romanian deadlift', 'glutes', 'dumbbell', 'beginner', 'A hip hinge that trains hamstrings and glutes and teaches you to lift with your hips, not your back.', '["Stand tall holding dumbbells in front of your thighs.","Soften your knees and push your hips back, sliding the weights down your legs.","Stop when you feel a strong stretch in your hamstrings, usually around mid-shin.","Squeeze your glutes and push your hips forward to stand."]'::jsonb, '["Hips go back, not down","Weights stay close to your legs","Neutral neck"]'::jsonb, '["Rounding the back to reach lower","Turning it into a squat by bending the knees a lot"]'::jsonb, array['Single-leg RDL','Glute bridge','Cable pull-through']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('hip-thrust', 'Hip thrust', 'glutes', 'barbell', 'beginner', 'The most direct glute builder. Works with a barbell, dumbbell or just bodyweight.', '["Sit with your upper back against a bench and the weight across your hips.","Plant your feet so your shins are vertical at the top.","Drive through your heels to lift your hips until your body is straight from knees to shoulders.","Pause, then lower with control."]'::jsonb, '["Tuck your chin and look forward","Ribs down at the top"]'::jsonb, '["Arching the lower back instead of extending the hips","Feet too far forward"]'::jsonb, array['Glute bridge','Single-leg glute bridge']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('glute-bridge', 'Glute bridge', 'glutes', 'bodyweight', 'beginner', 'A floor version of the hip thrust. Good at home and as a warm-up.', '["Lie on your back, knees bent, feet flat and hip-width apart.","Press through your heels and lift your hips.","Squeeze your glutes at the top for a second, then lower."]'::jsonb, '["Push the floor away with your heels","Keep ribs down"]'::jsonb, '["Pushing through the toes","Over-arching the back"]'::jsonb, array['Hip thrust','Single-leg glute bridge']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('walking-lunge', 'Walking lunge', 'legs', 'dumbbell', 'beginner', 'A single-leg exercise that builds legs and balance at the same time.', '["Hold dumbbells at your sides and stand tall.","Take a long step forward and lower your back knee towards the floor.","Push through the front foot to bring the back leg forward into the next step."]'::jsonb, '["Torso upright","Front knee over the middle of the foot"]'::jsonb, '["Steps too short so the front knee shoots forward","Wobbling side to side from a narrow stance"]'::jsonb, array['Reverse lunge','Split squat','Step-up']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('bulgarian-split-squat', 'Bulgarian split squat', 'legs', 'dumbbell', 'intermediate', 'A demanding single-leg squat with the back foot on a bench. Great when you only have light dumbbells.', '["Stand a stride in front of a bench and rest the top of your back foot on it.","Lower straight down until the back knee nearly touches the floor.","Drive up through the front heel."]'::jsonb, '["Most weight on the front leg","Slight forward lean is fine"]'::jsonb, '["Standing too close to the bench","Bouncing out of the bottom"]'::jsonb, array['Split squat','Reverse lunge','Step-up']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('step-up', 'Step-up', 'legs', 'dumbbell', 'beginner', 'A simple single-leg move using a box, bench or a stair.', '["Place one foot fully on a stable box or step.","Push through that foot to stand up on the box.","Lower slowly with the same leg and repeat."]'::jsonb, '["Let the top leg do the work","Control the way down"]'::jsonb, '["Pushing off with the back foot","Using a box so high your hip drops"]'::jsonb, array['Reverse lunge','Split squat']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('push-up', 'Push-up', 'chest', 'bodyweight', 'beginner', 'The most useful upper-body exercise you can do anywhere. Scale it with an incline.', '["Hands slightly wider than shoulders, body in a straight line from head to heels.","Lower your chest towards the floor with elbows about 45° from your body.","Push back up to straight arms."]'::jsonb, '["Squeeze glutes and brace your stomach","Chest leads, not the hips"]'::jsonb, '["Hips sagging","Elbows flaring straight out to the sides"]'::jsonb, array['Incline push-up on a bench or wall','Knee push-up','Dumbbell bench press']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('incline-dumbbell-press', 'Incline dumbbell press', 'chest', 'dumbbell', 'beginner', 'Builds the upper chest and shoulders with a comfortable range of motion.', '["Set a bench to about 30°. Sit back with a dumbbell on each thigh.","Kick the weights up and lie back, dumbbells over your shoulders.","Lower until the weights are level with your chest, then press up."]'::jsonb, '["Shoulder blades pulled back and down","Forearms vertical"]'::jsonb, '["Bench set too steep, turning it into a shoulder press","Bouncing the weights at the bottom"]'::jsonb, array['Push-up','Machine chest press']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('barbell-bench-press', 'Barbell bench press', 'chest', 'barbell', 'intermediate', 'The main horizontal pressing lift. Always use safety arms or a spotter.', '["Lie with eyes under the bar, feet flat, shoulder blades squeezed together.","Grip slightly wider than shoulder-width and unrack.","Lower the bar to your lower chest with control.","Press up and slightly back towards your face."]'::jsonb, '["Keep your upper back tight","Wrists stacked over elbows"]'::jsonb, '["Bouncing the bar off the chest","Lifting the hips off the bench"]'::jsonb, array['Dumbbell bench press','Push-up','Machine chest press']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('dumbbell-shoulder-press', 'Dumbbell shoulder press', 'shoulders', 'dumbbell', 'beginner', 'A vertical press for shoulders and triceps. Seated is easiest to learn.', '["Sit upright with back support, dumbbells at shoulder height, palms forward.","Press the weights overhead until arms are straight.","Lower with control back to shoulder height."]'::jsonb, '["Ribs down, no big arch","Press slightly in front of your head"]'::jsonb, '["Leaning far back","Lowering only halfway"]'::jsonb, array['Landmine press','Pike push-up']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('lateral-raise', 'Lateral raise', 'shoulders', 'dumbbell', 'beginner', 'Light-weight work for the side delts. Strict form beats heavy weight here.', '["Stand with light dumbbells at your sides.","Raise your arms out to the side until they are level with your shoulders.","Lower slowly."]'::jsonb, '["Lead with the elbows","Slight bend in the arms"]'::jsonb, '["Swinging the body to lift","Shrugging the shoulders up"]'::jsonb, array['Cable lateral raise','Band lateral raise']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('lat-pulldown', 'Lat pulldown', 'back', 'machine', 'beginner', 'Builds the lats and is the stepping stone to pull-ups.', '["Sit with thighs under the pads and grip the bar slightly wider than shoulders.","Pull the bar to your upper chest, driving your elbows down.","Let the bar rise with control until arms are straight."]'::jsonb, '["Chest up","Pull with elbows, not hands"]'::jsonb, '["Leaning far back and yanking","Pulling the bar behind the neck"]'::jsonb, array['Assisted pull-up','Band pulldown','Inverted row']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('one-arm-dumbbell-row', 'One-arm dumbbell row', 'back', 'dumbbell', 'beginner', 'A supported row that lets you train each side of your back on its own.', '["Place one hand and knee on a bench, back flat.","Hold a dumbbell with the other arm hanging straight.","Pull the dumbbell towards your hip, then lower it fully."]'::jsonb, '["Elbow travels towards the hip","Keep the shoulders level"]'::jsonb, '["Twisting the torso to lift","Shrugging instead of rowing"]'::jsonb, array['Seated cable row','Chest-supported row','Inverted row']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('seated-cable-row', 'Seated cable row', 'back', 'cable', 'beginner', 'A steady pulling exercise for the middle back and lats.', '["Sit with knees slightly bent and hold the handle with arms straight.","Pull the handle to your stomach while squeezing your shoulder blades together.","Return slowly until your arms are straight."]'::jsonb, '["Sit tall","Pause with the handle at your stomach"]'::jsonb, '["Rocking back and forth","Rounding the back on the return"]'::jsonb, array['One-arm dumbbell row','Band row']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('inverted-row', 'Inverted row', 'back', 'bodyweight', 'beginner', 'A bodyweight row under a bar or sturdy table. Harder as your feet go further forward.', '["Lie under a bar set at waist height and grip it slightly wider than shoulders.","Keep your body straight from heels to head.","Pull your chest to the bar, then lower with control."]'::jsonb, '["Squeeze glutes so hips stay up","Shoulder blades together at the top"]'::jsonb, '["Hips sagging","Half reps"]'::jsonb, array['Band row','One-arm dumbbell row']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('dumbbell-biceps-curl', 'Dumbbell biceps curl', 'arms', 'dumbbell', 'beginner', 'Direct biceps work. Use a weight you can lift without swinging.', '["Stand with dumbbells at your sides, palms forward.","Curl the weights up by bending your elbows.","Lower slowly until your arms are straight."]'::jsonb, '["Elbows stay by your sides","Slow on the way down"]'::jsonb, '["Swinging the body","Cutting the bottom half of the rep"]'::jsonb, array['Hammer curl','Cable curl','Band curl']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('triceps-pushdown', 'Triceps pushdown', 'arms', 'cable', 'beginner', 'Isolates the triceps on a cable machine with a rope or bar.', '["Stand facing a high cable with a rope attachment.","Tuck your elbows by your sides.","Push the rope down until your arms are straight, then let it rise to about chest height."]'::jsonb, '["Upper arms stay still","Spread the rope at the bottom"]'::jsonb, '["Leaning over the rope and using bodyweight","Elbows drifting forward"]'::jsonb, array['Overhead dumbbell extension','Bench dip','Close-grip push-up']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('plank', 'Plank', 'core', 'bodyweight', 'beginner', 'Teaches you to brace your trunk, which carries over to every lift.', '["Forearms on the floor under your shoulders, legs straight behind you.","Lift your hips so your body forms a straight line.","Hold while breathing normally."]'::jsonb, '["Squeeze glutes","Pull elbows towards toes without moving them"]'::jsonb, '["Hips sagging or piking up","Holding your breath"]'::jsonb, array['Knee plank','Dead bug']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('dead-bug', 'Dead bug', 'core', 'bodyweight', 'beginner', 'A core exercise lying on your back that is easy on the spine.', '["Lie on your back with arms pointing at the ceiling and knees bent at 90° above your hips.","Press your lower back gently into the floor.","Slowly lower one arm and the opposite leg towards the floor, then return and switch."]'::jsonb, '["Lower back stays in contact with the floor","Move slowly"]'::jsonb, '["Arching the back as the leg lowers","Rushing the reps"]'::jsonb, array['Plank','Bird dog']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('side-plank', 'Side plank', 'core', 'bodyweight', 'beginner', 'Trains the sides of your trunk and hips.', '["Lie on your side with your elbow under your shoulder.","Lift your hips so your body is straight from head to feet.","Hold, then switch sides."]'::jsonb, '["Hips forward, not bent","Top shoulder stacked over the bottom one"]'::jsonb, '["Hips dropping","Rotating the chest towards the floor"]'::jsonb, array['Side plank from knees','Suitcase carry']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('farmer-carry', 'Farmer carry', 'full_body', 'dumbbell', 'beginner', 'Walk while holding heavy weights. Builds grip, core and posture with almost no learning curve.', '["Pick up a heavy dumbbell in each hand with a neutral spine.","Stand tall and walk with short, steady steps.","Set the weights down with control at the end."]'::jsonb, '["Shoulders down and back","Do not let the weights swing"]'::jsonb, '["Leaning to one side","Shrugging the shoulders up"]'::jsonb, array['Suitcase carry (one hand)','Bag carry with groceries']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('standing-calf-raise', 'Standing calf raise', 'legs', 'bodyweight', 'beginner', 'Strengthens the calves. Doable at a desk, in a queue, or on a step for more range.', '["Stand with the balls of your feet on a step, holding something for balance.","Rise up onto your toes as high as you can.","Lower your heels slowly below the step, then repeat."]'::jsonb, '["Pause at the top","Full stretch at the bottom"]'::jsonb, '["Bouncing","Bending the knees to cheat"]'::jsonb, array['Seated calf raise','Single-leg calf raise']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('brisk-walk', 'Brisk walk', 'cardio', 'bodyweight', 'beginner', 'The simplest cardio. Brisk means you can talk but not sing.', '["Walk at a pace that raises your breathing.","Swing your arms naturally and keep a tall posture.","Build up to 20 to 30 minutes, or several 10-minute walks across the day."]'::jsonb, '["Talk test: you can speak in sentences, not sing","A short walk after meals is a good habit"]'::jsonb, '["Strolling too slowly to count as brisk"]'::jsonb, array['Incline treadmill walk','Cycling','Stair climbing']::text[])
on conflict (slug) do nothing;
insert into public.exercises (slug, name, muscle_group, equipment, level, summary, steps, cues, mistakes, substitutions)
values ('hip-flexor-stretch', 'Kneeling hip flexor stretch', 'mobility', 'bodyweight', 'beginner', 'Opens up the front of the hips that get tight from long hours of sitting.', '["Kneel on one knee with the other foot in front, both knees at 90°.","Tuck your pelvis under and squeeze the glute of the back leg.","Shift forward slightly until you feel a stretch at the front of the back hip. Hold 30 to 45 seconds per side."]'::jsonb, '["Tuck the pelvis before moving forward","Stay tall"]'::jsonb, '["Arching the lower back to fake the stretch"]'::jsonb, array['Standing hip flexor stretch','Couch stretch']::text[])
on conflict (slug) do nothing;

